const point = 8000;

function getGrade() {
  if (point >= 5000) {
    return 'VIP';
  } else if (point >= 1000) {
    return '일반';
  } else {
    return '신규';
  }
}

function stockLabel(stock) {
  if (stock === 0) {
    return '품절';
  } else if (stock < 10) {
    return '재고 부족';
  } else {
    return '충분';
  }
}
